practice.solution:
package main

import (
	"fmt"
	"math"
)

func absInt(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	fmt.Println("smaller of -1.5 and 0.5:", math.Min(-1.5, 0.5))
	target, low, high := 50, 40, 60
	guesses := []int{38, 61, 55}
	closest := math.MaxInt64
	for _, g := range guesses {
		d := absInt(g - target)
		fmt.Printf("%d is off by %d, clamped to %d\n", g, d, minInt(maxInt(g, low), high))
		closest = minInt(closest, d)
	}
	fmt.Println("closest:", closest)
}

