package main

import "fmt"

func sumAll(nums ...int) int {
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

func maxOf(first int, rest ...int) int {
	best := first
	for _, n := range rest {
		if n > best {
			best = n
		}
	}
	return best
}

func main() {
	fmt.Println("sum of nothing:", sumAll())
	fmt.Println("sum of 4, 8, 15:", sumAll(4, 8, 15))
	scores := []int{72, 95, 88}
	fmt.Println("sum of scores:", sumAll(scores...))
	fmt.Println("max of 7:", maxOf(7))
	fmt.Println("max of 3, 9, 2:", maxOf(3, 9, 2))
	fmt.Println("max of scores:", maxOf(scores[0], scores[1:]...))
}

