practice.solution:
package main

import "fmt"

func average(nums ...float64) float64 {
	if len(nums) == 0 {
		return 0
	}
	total := 0.0
	for _, n := range nums {
		total += n
	}
	return total / float64(len(nums))
}

func minOf(first int, rest ...int) int {
	best := first
	for _, n := range rest {
		if n < best {
			best = n
		}
	}
	return best
}

func main() {
	fmt.Printf("average of nothing: %.2f\n", average())
	fmt.Printf("average of 2, 3, 7: %.2f\n", average(2, 3, 7))
	temps := []float64{18.5, 21.0, 19.25}
	fmt.Printf("average of temps: %.2f\n", average(temps...))
	fmt.Println("min of 5:", minOf(5))
	fmt.Println("min of 8, 3, 6:", minOf(8, 3, 6))
	ages := []int{34, 27, 41}
	fmt.Println("min of ages:", minOf(ages[0], ages[1:]...))
}

steps.body:
Go 1.16 has no `contains` or `indexOf` for slices, and no generics to write one helper for every type. The idiom is a short loop per element type you need. When a program needs the same helper for two types, put the type in the name: `containsString`, `containsInt`. (Strings already have `strings.Contains` and `strings.Index`.)

```go
func indexOf(nums []int, x int) int {
	for i, v := range nums {
		if v == x {
			return i
		}
	}
	return -1
}
```

- Return as soon as you find a match. That gives the **first** index and skips the rest of the slice.
- Return `-1` when the value is missing, the same convention as `strings.Index`. Valid indexes start at 0, so -1 can never be confused with a real position.
- A `contains` helper returns `true` on a match and `false` after the loop.
- To find the **last** match, loop backward from `len(s) - 1`.

Each search walks the slice, so it costs time proportional to its length. Later lessons show faster lookups.

example.code:
package main

import "fmt"

func contains(words []string, w string) bool {
	for _, v := range words {
		if v == w {
			return true
		}
	}
	return false
}

func indexOf(nums []int, x int) int {
	for i, v := range nums {
		if v == x {
			return i
		}
	}
	return -1
}

func main() {
	fruits := []string{"apple", "kiwi", "mango"}
	fmt.Println("has kiwi:", contains(fruits, "kiwi"))
	fmt.Println("has plum:", contains(fruits, "plum"))
	nums := []int{4, 8, 15, 16, 8}
	fmt.Println("index of 8:", indexOf(nums, 8))
	fmt.Println("index of 42:", indexOf(nums, 42))
}

