practice.solution:
package main

import "fmt"

func countOf(nums []int, x int) int {
	count := 0
	for _, v := range nums {
		if v == x {
			count++
		}
	}
	return count
}

func lastIndexOf(words []string, w string) int {
	for i := len(words) - 1; i >= 0; i-- {
		if words[i] == w {
			return i
		}
	}
	return -1
}

func main() {
	rolls := []int{3, 7, 3, 9, 3}
	fmt.Println("count of 3:", countOf(rolls, 3))
	fmt.Println("count of 5:", countOf(rolls, 5))
	cmds := []string{"go", "run", "go", "stop"}
	fmt.Println("last go:", lastIndexOf(cmds, "go"))
	fmt.Println("last jump:", lastIndexOf(cmds, "jump"))
}
